-- FrankiFlow bilingual editable service checklists
create table if not exists public.frankiflow_checklists (
  service_key text primary key check (service_key in ('buero','wohnung','airbnb','treppenhaus','deep','windows')),
  label_de text not null,
  label_en text not null,
  sections jsonb not null default '[]'::jsonb check (jsonb_typeof(sections) = 'array'),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id)
);

alter table public.frankiflow_checklists enable row level security;

do $$ begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='frankiflow_checklists' and policyname='frankiflow_public_checklists_read') then
    create policy frankiflow_public_checklists_read on public.frankiflow_checklists for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='frankiflow_checklists' and policyname='frankiflow_admin_checklists_all') then
    create policy frankiflow_admin_checklists_all on public.frankiflow_checklists for all to authenticated using (private.frankiflow_is_admin()) with check (private.frankiflow_is_admin());
  end if;
end $$;

grant select on public.frankiflow_checklists to anon, authenticated;
grant insert, update, delete on public.frankiflow_checklists to authenticated;

