insert into public.frankiflow_checklists (service_key,label_de,label_en,sections) values ('deep','Erweiterte Grundreinigung','Extended deep cleaning','[{"title_de":"Zusätzliche Grundreinigung – Oberflächen & Details","title_en":"Additional deep cleaning – surfaces & details","optional":false,"items":[{"de":"Türen und Türrahmen vollständig reinigen","en":"Clean doors and door frames thoroughly"},{"de":"Sockelleisten und sichtbare Kanten reinigen","en":"Clean skirting boards and visible edges"},{"de":"Heizkörper außen gründlich reinigen","en":"Deep-clean radiator exteriors"},{"de":"Lichtschalter, Türgriffe und Kontaktflächen intensiv reinigen","en":"Intensively clean light switches, handles and touch points"},{"de":"Schwerer erreichbare horizontale Oberflächen entstauben, soweit sicher zugänglich","en":"Dust less-accessible horizontal surfaces where safely reachable"},{"de":"Ecken, Randbereiche und sichtbare Ablagerungen gründlich bearbeiten","en":"Deep-clean corners, edges and visible build-up"},{"de":"Hartnäckige sichtbare Flecken intensiver behandeln, soweit materialverträglich","en":"Treat stubborn visible marks more intensively where material-safe"}]},{"title_de":"Zusätzliche Grundreinigung – Küche","title_en":"Additional deep cleaning – kitchen","optional":false,"items":[{"de":"Küchenarbeitsflächen intensiv reinigen","en":"Deep-clean kitchen work surfaces"},{"de":"Spüle und Armaturen gründlich reinigen und bei Bedarf entkalken","en":"Deep-clean and descale sink and taps where needed"},{"de":"Schrankfronten vollständig reinigen","en":"Clean cupboard fronts completely"},{"de":"Außenseiten von Küchengeräten gründlich reinigen","en":"Deep-clean appliance exteriors"},{"de":"Spritzbereiche und erreichbare Wandflächen reinigen","en":"Clean splash areas and accessible wall surfaces"},{"de":"Müllbereich gründlich reinigen","en":"Deep-clean the waste area"},{"de":"Bodenränder und Ecken intensiv reinigen","en":"Deep-clean floor edges and corners"}]},{"title_de":"Zusätzliche Grundreinigung – Bad & Sanitär","title_en":"Additional deep cleaning – bathroom & sanitary","optional":false,"items":[{"de":"Sanitärobjekte intensiv reinigen und desinfizieren","en":"Intensively clean and disinfect sanitary fixtures"},{"de":"Armaturen und erreichbare Kalkablagerungen gründlicher entfernen","en":"Remove accessible limescale from taps and fittings more thoroughly"},{"de":"Dusche bzw. Badewanne intensiv reinigen","en":"Deep-clean shower or bathtub"},{"de":"Erreichbare Fliesen- und Wandflächen reinigen","en":"Clean accessible tiles and wall surfaces"},{"de":"Spiegel und Glasflächen gründlich reinigen","en":"Deep-clean mirrors and glass surfaces"},{"de":"Bodenränder, Ecken und schwerer erreichbare Bereiche intensiv reinigen","en":"Deep-clean floor edges, corners and less-accessible areas"}]},{"title_de":"Nur nach ausdrücklicher Vereinbarung","title_en":"Only when specifically agreed","optional":true,"items":[{"de":"Kühlschrank-Innenreinigung","en":"Refrigerator interior cleaning"},{"de":"Schrank-Innenreinigung","en":"Cupboard interior cleaning"},{"de":"Teppich-Tiefenreinigung","en":"Carpet deep cleaning"},{"de":"Weitere objektspezifische Zusatzleistungen","en":"Other property-specific additional services"}]}]'::jsonb) on conflict (service_key) do nothing;
insert into public.frankiflow_checklists (service_key,label_de,label_en,sections) values ('windows','Fensterreinigung','Window cleaning','[{"title_de":"Fenster & Glasflächen","title_en":"Windows & glass","optional":false,"items":[{"de":"Vereinbarte Fensterscheiben reinigen","en":"Clean agreed window panes"},{"de":"Innen- und Außenseiten reinigen, soweit sicher zugänglich und vereinbart","en":"Clean inside and outside where safely accessible and agreed"},{"de":"Sichtbare Flecken, Fingerabdrücke und normale Verschmutzungen entfernen","en":"Remove visible marks, fingerprints and normal dirt"},{"de":"Glas streifenarm nacharbeiten","en":"Finish glass with a low-streak result"},{"de":"Vereinbarte Glastüren bzw. Glasflächen reinigen","en":"Clean agreed glass doors or other glass surfaces"}]},{"title_de":"Rahmen, Falze & Fensterbänke","title_en":"Frames, rebates & window sills","optional":false,"items":[{"de":"Fensterrahmen innen/außen abwischen, soweit vereinbart","en":"Wipe window frames inside/outside where agreed"},{"de":"Erreichbare Rahmenkanten und Falzbereiche reinigen","en":"Clean accessible frame edges and rebate areas"},{"de":"Fenstergriffe reinigen","en":"Clean window handles"},{"de":"Fensterbänke innen reinigen","en":"Clean interior window sills"},{"de":"Fensterbänke außen reinigen, soweit sicher zugänglich und vereinbart","en":"Clean exterior window sills where safely accessible and agreed"}]}]'::jsonb) on conflict (service_key) do nothing;